// AFTER: 'DRY-ed' into one helper with a flag per caller
+function sendEmail(user: User, kind: 'welcome' | 'reset', opts?: { token?: string }) {
+  let subject: string, body: string;
+  if (kind === 'welcome') {
+    subject = `Welcome, ${user.name}`;
+    body = welcomeBody(user);
+  } else {
+    subject = 'Reset your password';
+    body = resetBody(user, opts!.token!); // throws if token missing
+  }
+  return mailer.send(user.email, subject, body);
+}
